impl MediaPlayer {
    /// Cancel the periodic reporter and the debounced seek, and release the pipeline.
    fn teardown(self) {
        if let Some(timer) = self.timer {
            timer.remove();
        }
        if let Some(seek) = self.seek_timer.borrow_mut().take() {
            seek.remove();
        }
