import re
from collections import Counter
def section(path, name=None):
    lines = open(path).read().splitlines()
    items = []
    if name:
        for i, ln in enumerate(lines):
            if ln.startswith(name):
                for n in lines[i+1:]:
                    if n.startswith("## "): break
                    m = re.match(r"^\d+\.\s+(.*)$", n)
                    if m: items.append(m.group(1).strip())
                break
    else:
        for ln in lines:
            m = re.match(r"^\d+\.\s+(.*)$", ln)
            if m: items.append(m.group(1).strip())
