/// --- stall diagnostics (debug aid for the "UI freezes mid-song" report) ---
/// Every renderer glib source stamps the last-tick timestamp and its own source
/// tag; a background watchdog thread reports any main-loop stall >3 s, and which
/// renderer source was last running when it froze.
const SRC_EMIT: u32 = 1;
const SRC_PUMP: u32 = 2;
const SRC_MEDIA: u32 = 3;
const SRC_SEEK: u32 = 4;

static LAST_TICK: AtomicU64 = AtomicU64::new(0);
static LAST_SOURCE: AtomicU32 = AtomicU32::new(0);

fn diag_tick(src: u32) {
    LAST_SOURCE.store(src, Ordering::Relaxed);
    LAST_TICK.store(monotonic_ms(), Ordering::Relaxed);
}

fn start_stall_watchdog() {
    static STARTED: std::sync::Once = std::sync::Once::new();
    STARTED.call_once(|| {
        std::thread::spawn(|| loop {
            std::thread::sleep(Duration::from_millis(1000));
            let last = LAST_TICK.load(Ordering::Relaxed);
            let now = monotonic_ms();
            if last != 0 && now.saturating_sub(last) > 3000 {
                eprintln!(
                    "[watchdog] MAIN-LOOP STALL for {} ms — last renderer source was #{}",
                    now - last,
                    LAST_SOURCE.load(Ordering::Relaxed)
                );
            }
        });
    });
}

