/// Apply pending frames to the renderer, returning how many were applied.
/// (Events flow the other way: the renderer writes them; the host drains them —
/// see [`Pump`].)
fn pump_once<P>(renderer: &Rc<RefCell<GtkRenderer>>, pump: &Rc<RefCell<P>>) -> u32
where
    P: Pump,
{
    let mut applied = 0u32;
    loop {
        let mut pump_ref = pump.borrow_mut();
        match pump_ref.next_frame() {
            Ok(Some(batch)) => {
                let frame = batch.frame();
                renderer.borrow_mut().apply_frame(frame);
                applied += 1;
            }
            _ => break,
        }
    }
    applied
}

