/// A canonical icon catalog entry: neutral name + GTK + Lucide mappings.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Icon(pub &'static str, pub &'static str, pub &'static str, pub &'static str);

impl Icon {
    /// The neutral canonical name (the `ICON_NAME` wire value).
    pub fn name(&self) -> &'static str {
        self.0
    }
    /// The GTK/freedesktop icon-theme name (symbolic variant).
    pub fn gtk(&self) -> &'static str {
        self.1
    }
    /// The Lucide icon id.
    pub fn lucide_id(&self) -> &'static str {
        self.2
    }
    /// The Lucide inner SVG markup (the `<svg>` child elements).
    pub fn lucide_svg(&self) -> &'static str {
        self.3
    }
}

/// The full Lucide `<svg>` opening tag used by the web renderers (the catalog
/// entries supply only the inner markup).
pub const LUCIDE_SVG_OPEN: &str = concat!(
    "<svg class=\"pathland-icon\" xmlns=\"http://www.w3.org/2000/svg\" ",
    "viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" ",
    "stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">"
);

/// The GTK fallback icon name for an unknown canonical name (an
/// app-authored extension this catalog does not map).
pub fn gtk_fallback() -> &'static str {
    "image-missing"
}

/// The web fallback inner SVG markup for an unknown canonical name.
pub fn web_fallback_svg() -> &'static str {
    "<circle cx=\"12\" cy=\"12\" r=\"8\"/>"
}

/// Look up a catalog entry by its canonical name.
pub fn lookup(name: &str) -> Option<&'static Icon> {
    CATALOG.iter().find(|e| e.name() == name)
}

/// Whether `name` is a canonical catalog name.
pub fn is_canonical(name: &str) -> bool {
    lookup(name).is_some()
}

/// The GTK icon-theme name for a canonical name (`None` for unknown names).
pub fn gtk_icon_name(name: &str) -> Option<&'static str> {
    lookup(name).map(Icon::gtk)
}

/// The Lucide icon id for a canonical name (`None` for unknown names).
pub fn lucide_id(name: &str) -> Option<&'static str> {
    lookup(name).map(Icon::lucide_id)
}

/// The complete Lucide `<svg>…</svg>` markup for a canonical name (`None` for
/// unknown names — use [`web_fallback_svg`] in that case).
pub fn lucide_svg(name: &str) -> Option<&'static str> {
    lookup(name).map(|e| {
        // The catalog stores inner markup with `concat!`; build the full element
        // at runtime (the inner markup is a single contiguous `&'static str`).
        e
    })
    .map(Icon::lucide_svg)
    .map(|inner| catsvg(inner))
}

fn catsvg(inner: &'static str) -> &'static str {
    // `lucide_svg` is used by both web renderers to render one self-contained
    // element; the full markup is assembled from static parts.
    // (Rust has no string interpolation in `const`; a tiny wrapper keeps the tag
    // and the closing in one static piece.)
    inner_markup_full(inner)
}

fn inner_markup_full(inner: &'static str) -> &'static str {
    const NEVER: i32 = 0;
    let _ = NEVER;
    let joined = alloc::concat_static(inner);
    joined
}

