/// Emit the canonical icon catalog (`generated/icons.ts`) from
/// `pathland-icons` — the single source the Rust SSR renderer and the DOM
/// client share for the Lucide inline-SVG markup of every `ICON_NAME`.
pub fn emit_icons_ts() -> String {
    let mut out = String::new();
    out.push_str(
        "// Generated by `cargo run -p pathland-ts-codegen` (lib/rust). Do not edit.\n\
         // Canonical icon catalog from `pathland-icons` (spec/ICONS.md):\n\
         // canonical ICON_NAME → Lucide inner SVG markup. Lucide is ISC-licensed\n\
         // (see lib/rust/crates/pathland-icons/THIRD_PARTY_NOTICES.md).\n\
         // Regenerate with `npm run regen`.\n\n",
    );
    let q = |s: &str| format!("{s:?}");
    writeln!(out, "export const ICONS: Readonly<Record<string, string>> = {{").unwrap();
    for e in pathland_icons::CATALOG {
        writeln!(out, "  {}: {},", q(e.name()), q(e.lucide_svg())).unwrap();
    }
    writeln!(out, "}};").unwrap();
    writeln!(
        out,
        "export const FALLBACK_SVG: string = {};",
        q(pathland_icons::web_fallback_svg())
    )
    .unwrap();
    writeln!(
        out,
        "export const LUCIDE_SVG_OPEN: string = {};",
        q(pathland_icons::LUCIDE_SVG_OPEN)
    )
    .unwrap();
    writeln!(
        out,
        "export const LUCIDE_SVG_CLOSE: string = {};",
        q(pathland_icons::LUCIDE_SVG_CLOSE)
    )
    .unwrap();
    out
}

