header = """//! # pathland-icons
//!
//! The **canonical icon catalog** for the Pathland `ICON` primitive
//! (spec/ICONS.md): a curated set of **neutral, semantic names** written once in
//! the UI model and mapped by each renderer onto its **native icon set** —
//! Adwaita/freedesktop symbolic icons on GTK, the **Remix Icon** set (filled) on
//! the web (inline SVG, single-sourced here so SSR and the DOM client agree).
//!
//! The catalog is `no_std` const data only. It is the **single source of truth**
//! for:
//!
//! - the canonical vocabulary (`CATALOG`),
//! - the GTK icon-theme name ([`gtk_icon_name`]),
//! - the Remix icon id + filled inline SVG markup ([`remix_id`], [`web_inner`]) —
//!   also emitted to the DOM client by `pathland-ts-codegen` as
//!   `generated/icons.ts`.
//!
//! Adding an icon = adding one catalog row (+ a Remix `-fill` glyph + a GTK
//! name), then regenerating. Unknown names (an app-authored extension) resolve
//! to renderer fallbacks: [`gtk_fallback`] on GTK, an empty-slot placeholder on
//! the web.

#![no_std]
#[cfg(test)]
extern crate std;

/// The canonical catalog: `(canonical name, GTK icon-name, Remix id, inner SVG markup)`.
///
/// The inner SVG markup is a **single filled** Remix `<path>` — the web renderers
/// wrap it in [`WEB_SVG_OPEN`]…[`WEB_SVG_CLOSE`] (`fill="currentColor"`, so
/// `COLOR`/`foregroundStyle` tint it). Vendored from the Remix Icon set
/// (Apache-2.0; see `THIRD_PARTY_NOTICES.md`).
pub const CATALOG: &[Icon] = &[
"""
