];

/// A canonical icon catalog entry: neutral name + GTK + Remix (filled) mappings.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Icon(pub &'static str, pub &'static str, pub &'static str, pub &'static str);

impl Icon {
    /// The neutral canonical name (the `ICON_NAME` wire value).
    pub fn name(&self) -> &'static str {
        self.0
    }
    /// The GTK/freedesktop icon-theme name (symbolic variant).
    pub fn gtk(&self) -> &'static str {
        self.1
    }
    /// The Remix icon id (the `-fill` variant's base name).
    pub fn remix_id(&self) -> &'static str {
        self.2
    }
    /// The inner SVG markup (a filled Remix `<path>`).
    pub fn web_inner(&self) -> &'static str {
        self.3
    }
}

/// The filled `<svg>` opening tag used by the web renderers (the catalog
/// entries supply only the inner markup). `fill="currentColor"` tints the glyph
/// via the node's `COLOR`/`foregroundStyle`.
pub const WEB_SVG_OPEN: &str = concat!(
    "<svg class=\\"pathland-icon\\" xmlns=\\"http://www.w3.org/2000/svg\\" ",
    "viewBox=\\"0 0 24 24\\" fill=\\"currentColor\\">"
);

/// The closing `</svg>` tag.
pub const WEB_SVG_CLOSE: &str = "</svg>";

/// The GTK fallback icon name for an unknown canonical name (an
/// app-authored extension this catalog does not map).
pub fn gtk_fallback() -> &'static str {
    "image-missing"
}

/// The web fallback inner SVG markup for an unknown canonical name.
pub fn web_fallback_svg() -> &'static str {
    "<circle cx=\\"12\\" cy=\\"12\\" r=\\"8\\"/>"
}

/// Look up a catalog entry by its canonical name.
pub fn lookup(name: &str) -> Option<&'static Icon> {
    CATALOG.iter().find(|e| e.name() == name)
}

/// Whether `name` is a canonical catalog name.
pub fn is_canonical(name: &str) -> bool {
    lookup(name).is_some()
}

/// The GTK icon-theme name for a canonical name (`None` for unknown names).
pub fn gtk_icon_name(name: &str) -> Option<&'static str> {
    lookup(name).map(Icon::gtk)
}

/// The Remix icon id for a canonical name (`None` for unknown names).
pub fn remix_id(name: &str) -> Option<&'static str> {
    lookup(name).map(Icon::remix_id)
}

/// The filled inner SVG markup for a canonical name (`None` for unknown names —
/// fall back to [`web_fallback_svg`]). Callers wrap it in
/// [`WEB_SVG_OPEN`]…[`WEB_SVG_CLOSE`].
pub fn web_inner(name: &str) -> Option<&'static str> {
    lookup(name).map(Icon::web_inner)
}

#[cfg(test)]
mod tests {
    use std::collections::HashSet;

    #[test]
    fn every_catalog_entry_resolves_on_all_renderers() {
        for e in super::CATALOG {
            assert!(super::is_canonical(e.name()));
            assert!(super::gtk_icon_name(e.name()).is_some(), "{} lacks a GTK name", e.name());
            assert!(super::remix_id(e.name()).is_some(), "{} lacks a Remix id", e.name());
            assert!(super::web_inner(e.name()).is_some(), "{} lacks web markup", e.name());
            assert!(e.web_inner().contains('>'), "{} svg has inner elements", e.name());
            // Filled glyphs: a single element, no stroke.
            assert!(e.web_inner().starts_with("<path"), "{} is a filled path", e.name());
            assert!(!e.web_inner().contains("stroke="), "{} has no stroke", e.name());
        }
    }

    #[test]
    fn canonical_names_are_unique() {
        let mut seen = HashSet::new();
        for e in super::CATALOG {
            assert!(seen.insert(e.name()), "duplicate canonical name {}", e.name());
        }
    }

    #[test]
    fn unknown_names_resolve_to_fallbacks() {
        assert!(!super::is_canonical("definitely-not-an-icon"));
        assert_eq!(super::gtk_icon_name("definitely-not-an-icon"), None);
        assert_eq!(super::web_inner("definitely-not-an-icon"), None);
        assert_eq!(super::gtk_fallback(), "image-missing");
        assert!(super::web_fallback_svg().contains("circle"));
    }
}
"""

