/// Emit the canonical icon catalog (`generated/icons.ts`) from
/// `pathland-render-html` — the web renderer owns the canonical `ICON_NAME` →
/// filled glyph map (`icons`); this mirrors it to the DOM client so SSR and the
/// client render exactly the same markup for every `ICON_NAME`.
pub fn emit_icons_ts() -> String {
    let mut out = String::new();
    out.push_str(
        "// Generated by `cargo run -p pathland-ts-codegen` (lib/rust). Do not edit.\n\
         // Canonical icon catalog — the web renderer's own mapping\n\
         // (`pathland-render-html::icons`, spec/ICONS.md): canonical ICON_NAME →\n\
         // Remix Icon **filled** inner SVG markup (Apache-2.0; see\n\
         // lib/rust/crates/pathland-render-html/THIRD_PARTY_NOTICES.md).\n\
         // Regenerate with `npm run regen`.\n\n",
    );
    let q = |s: &str| format!("{s:?}");
    writeln!(out, "export const ICONS: Readonly<Record<string, string>> = {{").unwrap();
    use pathland_core::icon;
    use pathland_render_html::icons as web_icons;
    for name in icon::NAMES {
        let inner = web_icons::web_inner(name).expect("canonical icon has a web glyph");
        writeln!(out, "  {}: {},", q(name), q(inner)).unwrap();
    }
    writeln!(out, "}};").unwrap();
    writeln!(
        out,
        "export const FALLBACK_SVG: string = {};",
        q(web_icons::web_fallback_svg())
    )
    .unwrap();

