    setIcon(target, "");

    expect(target.innerHTML).toContain("circle");
    expect(target.hasAttribute("data-pathland-icon")).toBe(false);
  });

  it("toggles a hydrated icon in place (play→pause→play) without pasting its own glyph", async () => {
    // The real play/pause button: an SSR svg in the document advertising "play"
    // with the play glyph inline. A delta to "pause" must NOT copy the element's
    // own stale glyph back (the regression: embeddedGlyph matched the element
    // after its attr was rewritten, so the icon never changed).
    const fetch = fetchByGlyph({ play: PLAY_PATH, pause: PAUSE_PATH });
    const button = iconSvg();
    button.setAttribute("data-pathland-icon", "play");
    button.innerHTML = PLAY_PATH;
    document.body.appendChild(button);

    setIcon(button, "pause");

    // It changed away from the pasted play glyph (fallback first)…
    expect(button.innerHTML).not.toContain('d="M19.376');
    expect(button.innerHTML).toContain("circle");
