/// advanced at least one cadence step (`TIME_REPORT_MAX_INTERVAL_S` — up to
/// ~30/s) since the last report, the cap the web client uses so both
/// renderers follow their native position source without flooding the socket.
fn should_report_time(last_seconds: f32, current_seconds: f32) -> bool {
    (current_seconds - last_seconds).abs() >= TIME_REPORT_MAX_INTERVAL_S
}

