/// Decode a `LIST` arena entry (`[u32 count][f32 × count]`) as a CSV string
/// with trimmed thresholds (e.g. `"0,640"`) — the `FIT_QUERY` mirror the fit
/// slot's allocator uses to derive the selected candidate.
fn list_csv(bytes: &[u8]) -> Option<String> {
    if bytes.len() < 4 {
        return None;
    }
    let count = u32::from_le_bytes(bytes[0..4].try_into().ok()?) as usize;
    if bytes.len() < 4 + count * 4 {
        return None;
    }
    let mut parts = Vec::with_capacity(count);
    for i in 0..count {
        let bits = u32::from_le_bytes(bytes[4 + 4 * i..8 + 4 * i].try_into().ok()?);
        let value = f32::from_bits(bits);
        parts.push(if value.fract() == 0.0 {
            format!("{:.0}", value)
        } else {
            format!("{:.1}", value)
        });
    }
    Some(parts.join(","))
}

